package li.cil.oc.vm.simulated;

import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
import static li.cil.oc.vm.simulated.QmpFixtureTest.*;
import li.cil.oc.api.vm.v2.SessionV2;

public class QmpCodecTest {
 private void bad(String wire)throws Exception{QmpCodec c=new QmpCodec();rejects(IllegalArgumentException.class,()->c.feed(bytes(wire),m->{}));assertEquals(0,c.retainedBytes());rejects(IllegalStateException.class,()->c.feed(bytes(GREETING),m->{}));}
 @Test public void partialAndMultipleFramesHaveNoPrematurePublication(){QmpCodec c=new QmpCodec();List<QmpCodec.Message> out=new ArrayList<>();byte[] b=bytes(GREETING);c.feed(Arrays.copyOf(b,b.length-1),out::add);assertTrue(out.isEmpty());c.feed(new byte[]{10},out::add);c.feed(bytes(GREETING),out::add);assertEquals(2,out.size());assertEquals(QmpCodec.Kind.GREETING,out.get(0).kind);assertEquals(0,c.retainedBytes());}
 @Test public void malformedUtf8AndBareLfFailClosed()throws Exception{QmpCodec c=new QmpCodec();rejects(IllegalArgumentException.class,()->c.feed(new byte[]{(byte)0xc3,40,13,10},m->{}));bad(GREETING.replace("\r\n","\n"));}
 @Test public void duplicateUnknownTrailingAndWrongTypesFailClosed()throws Exception{bad("{\"QMP\":{},\"QMP\":{}}\r\n");bad("{\"run-shell\":\"bad\"}\r\n");bad(GREETING.trim()+" {}\r\n");bad("{\"return\":{},\"id\":1}\r\n");bad("{\"event\":\"HOST_INPUT\",\"data\":{}}\r\n");bad("{\"return\":[],\"id\":\""+UUID.randomUUID()+"\"}\r\n");}
 @Test public void structureAndNumberBoundsFailClosed()throws Exception{String body="{}";for(int i=0;i<9;i++)body="{\"x\":"+body+"}";bad("{\"return\":"+body+",\"id\":\""+UUID.randomUUID()+"\"}\r\n");bad(GREETING.replace("\"major\":9","\"major\":1.5"));bad(GREETING.replace("\"micro\":0","\"micro\":1001"));bad("{\"event\":\"STOP\",\"data\":{},\"timestamp\":{\"seconds\":0,\"microseconds\":1000000}}\r\n");}
 @Test public void lineAndLifetimeByteCapsAreEnforced()throws Exception{QmpCodec line=new QmpCodec();byte[] huge=new byte[QmpCodec.MAX_LINE+1];Arrays.fill(huge,(byte)'a');rejects(IllegalArgumentException.class,()->line.feed(huge,m->{}));assertEquals(0,line.retainedBytes());QmpCodec total=new QmpCodec();byte[] b=bytes(GREETING);while(total.lifetimeBytes()+b.length<=QmpCodec.MAX_TOTAL)total.feed(b,m->{});rejects(IllegalArgumentException.class,()->total.feed(new byte[QmpCodec.MAX_TOTAL-total.lifetimeBytes()+1],m->{}));}
 @Test public void commandsAreFiniteAndHaveNoArgumentsOrHostPaths(){for(QmpCodec.Command c:QmpCodec.Command.values()){String s=new String(QmpCodec.command(c,UUID.randomUUID()),java.nio.charset.StandardCharsets.UTF_8);assertTrue(s.endsWith("\r\n"));assertFalse(s.contains("arguments"));assertFalse(s.contains("screendump"));assertFalse(s.contains("filename"));}}
 @Test public void transportCopiesBoundsQueuesAndRetainsLifetimeOnClose()throws Exception{MemoryQmpTransport t=new MemoryQmpTransport();byte[] data={1};t.feedFixture(data);data[0]=2;assertArrayEquals(new byte[]{1},t.receive());for(int i=0;i<32;i++)t.feedFixture(new byte[]{1});rejects(IllegalArgumentException.class,()->t.feedFixture(new byte[]{1}));t.close();assertEquals(33,t.lifetimeBytes());assertEquals(0,t.retainedChunks());rejects(IllegalStateException.class,()->t.feedFixture(new byte[]{1}));}
 @Test public void transportCannotBeSharedAcrossSessions()throws Exception{try(H h=new H()){SessionV2 other=new SessionV2.Pool(1).open(h.identity,a->true,2,0,CANVAS,0);rejects(IllegalStateException.class,()->new QmpFixtureController(other,h.io,0));other.revoke();assertTrue(h.io.takeRequests().isEmpty());}}
 @Test public void transportLifetimeBoundsSurviveDrain()throws Exception{MemoryQmpTransport t=new MemoryQmpTransport();byte[] chunk=new byte[8192];for(int i=0;i<32;i++){t.feedFixture(chunk);assertEquals(8192,t.receive().length);}rejects(IllegalArgumentException.class,()->t.feedFixture(new byte[]{1}));assertEquals(262144,t.lifetimeBytes());t.close();}
}
